// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    // Fuzz on caller address `caller` and a nonzero value `deposit` sent into c before withdrawAll.
    // We deploy a RevertingReceiver that always reverts on receive so that withdrawAll's internal
    // transfer will fail in the same way for both reference and mutant; the difference is who is
    // permitted to call withdrawAll and observe success vs revert.
    function testFuzz_property(address caller, uint256 deposit) public {
        vm.assume(deposit <= VALUE_CAP);
        // keep deposit in a practical range but wide enough to include 0 and many values
        deposit = bound(deposit, 0, 1 ether);

        // fund caller so they can send Ether when needed
        vm.deal(caller, deposit);

        // send some Ether to the contract so withdrawAll has a balance to attempt to transfer
        if (deposit > 0) {
            vm.prank(caller);
            (bool sent, ) = address(c).call{value: deposit}("");
            // the above fallback increments depositsCount in C; we don't assert on that here
            require(sent, "funding c failed in test setup");
        }

        // Deploy a receiver that will always revert on receiving Ether so the transfer in withdraw will fail.
        RevertingReceiver rr = new RevertingReceiver();

        // The reference contract only allows owner to call withdrawAll successfully. We assert a general
        // invariant: for ANY caller address, if calling withdrawAll returns (ok==true) then the caller must be owner.
        // We exercise the call from `caller` and observe whether it succeeded or reverted.

        bool ok;
        vm.prank(caller);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The single assertion: if the call succeeded, the caller equals the owner recorded by c.
        // This holds for the REFERENCE for all inputs; the MUTANT (which permits address(0)) will allow
        // caller == address(0) to succeed, violating this property for that input.
        assertTrue(!ok || caller == c.owner());
    }
}

contract RevertingReceiver {
    receive() external payable {
        revert("revert on receive");
    }
}
